/// What a kind of thing takes, asked by name — `ux-44`.
///
/// **"Read the subtypes" is not an answer a program can act on.** `addModifier`
/// takes an object naming a kind and that kind's own fields, and the only
/// place those fields were written down was a paragraph inside the tool's own
/// description — three hundred words covering five kinds, which an agent has
/// to read in full to find the two it wants. The same held for a parametric
/// shape's parameters and for a texture node's sockets.
///
/// **Generated by making one and asking it what it writes.** Every kind here
/// has a `toJson` that the project format already reads back, and the
/// modifiers additionally have `hintsForModifier` — the table an inspector
/// builds its sliders from, with the ranges and the units in it. So this makes
/// one of each with ordinary values and reports what came out, which cannot
/// drift from what the readers accept: a field added to a modifier appears
/// here the day it is written.
library;

import 'package:flutter3d_mesh/flutter3d_mesh.dart';
import 'package:flutter3d_model_core/flutter3d_model_core.dart';
import 'package:vector_math/vector_math.dart';

/// The families `describeType` can be asked about.
const List<String> describableFamilies = <String>[
  'modifier',
  'shape',
  'textureNode',
];

/// One of each modifier kind, with values that mean nothing in particular —
/// they are here to be asked what fields they have, not to be applied.
List<Modifier> _modifiers() => <Modifier>[
  ArrayModifier(count: 2, offset: Vector3(1, 0, 0)),
  MirrorModifier(normal: Vector3(1, 0, 0)),
  const SmoothModifier(iterations: 1),
  const SubdivisionModifier(levels: 1),
  BooleanModifier(
    operation: CsgOperation.union,
    operandId: 0,
    operandTransform: Matrix4.identity(),
  ),
];

/// One of each parametric shape.
List<ParametricShape> _shapes() => <ParametricShape>[
  ParametricCuboid(),
  const ParametricPlane(),
  const ParametricSphere(),
  const ParametricCylinder(),
  const ParametricTorus(),
];

/// One of each texture node, ids all zero for the same reason.
List<TextureNode> _textureNodes() => <TextureNode>[
  const ImageTextureNode(id: 0, imageId: 0),
  ColorTextureNode(id: 0, value: Vector4(1, 1, 1, 1)),
  const BlendTextureNode(id: 0, factor: 0.5),
  const ChannelsTextureNode(id: 0, channel: TextureChannel.r),
  const LevelsTextureNode(id: 0),
  const InvertTextureNode(id: 0),
  const OutputTextureNode(id: 0),
];

/// What [kind] takes, or — with no [kind] — every kind of [family] at once.
///
/// [family] is one of [describableFamilies]. An unknown family or kind is an
/// answer naming what there is, not an empty one: the question "what kinds are
/// there" and "what does this one take" are the same question asked twice, and
/// a caller that got the first one wrong has asked the second.
String describeType({required String family, String? kind}) {
  final Map<String, Map<String, Object?>> table = switch (family) {
    'modifier' => <String, Map<String, Object?>>{
      for (final Modifier it in _modifiers())
        it.toJson()['kind']! as String: it.toJson(),
    },
    'shape' => <String, Map<String, Object?>>{
      for (final ParametricShape it in _shapes())
        parametricShapeJson(it)['shape']! as String: parametricShapeJson(it),
    },
    // A node's own `kind` is a getter rather than a key in its `toJson` —
    // `TextureGraph.toJson` writes the two side by side, and this does the
    // same so the field list reads the way the file does.
    'textureNode' => <String, Map<String, Object?>>{
      for (final TextureNode it in _textureNodes()) it.kind: it.toJson(),
    },
    _ => const <String, Map<String, Object?>>{},
  };
  if (table.isEmpty) {
    return '"$family" is not a family this describes; it is '
        '${describableFamilies.join(', ')}';
  }

  final Map<String, ParamHint> hints = <String, ParamHint>{
    if (family == 'modifier')
      for (final Modifier it in _modifiers())
        if (kind == null || it.toJson()['kind'] == kind)
          ...hintsForModifier(it),
  };

  if (kind == null) {
    return <String>[
      '$family kinds: ${table.keys.join(', ')}',
      'ask again with a "kind" for that one\'s own fields',
    ].join('\n');
  }
  final Map<String, Object?>? fields = table[kind];
  if (fields == null) {
    return '"$kind" is not a $family; it is one of ${table.keys.join(', ')}';
  }
  return <String>[
    '$family "$kind" takes:',
    for (final MapEntry<String, Object?> field in fields.entries)
      if (field.key != 'kind' && field.key != 'shape' && field.key != 'id')
        _field(field.key, field.value, hints[field.key]),
  ].join('\n');
}

String _field(String name, Object? value, ParamHint? hint) =>
    '  $name: ${_shapeOf(value)}${_hint(hint)}';

/// What a field's own example value says about its shape.
String _shapeOf(Object? value) => switch (value) {
  final bool _ => 'true or false',
  final int _ => 'a whole number',
  final double _ => 'a number',
  final String _ => 'a word',
  final List<Object?> list => '${list.length} numbers',
  final Map<Object?, Object?> _ => 'an object',
  null => 'optional; omit it or give a number',
  _ => 'a value',
};

/// The range and unit an inspector would build a slider from, when there is
/// one — the same table `modifier_slot.dart` already keeps for the panels.
String _hint(ParamHint? hint) => switch (hint) {
  null => '',
  IntHint(:final min, :final max) => ', $min to $max',
  DoubleHint(:final min, :final max, :final unit) =>
    ', ${min ?? '−∞'} to ${max ?? '∞'}${unit == null ? '' : ' ($unit)'}',
  Vector3Hint(:final unit) => unit == null ? '' : ' (in $unit)',
  EnumHint(:final values) => ', one of ${values.join(', ')}',
  BoolHint() => '',
};
